-- ----------sql1------------
-- 32
SELECT MIN(POSTS.CREAIONDATE) AS FIRSTPOSTCREATIONDATE FROM POSTS INNER JOIN USERS ON POSTS.OWNERUSERID = USERS.ID WHERE USERS.ID = (SELECT MIN(USERS.ID) FROM USERS);
-- ----------sql2------------
SELECT T2.CREAIONDATE FROM USERS AS T1 INNER JOIN POSTS AS T2 ON T1.ID = T2.OWNERUSERID WHERE T1.AGE IS NOT NULL ORDER BY T1.AGE, T2.CREAIONDATE LIMIT 1;

