SELECT CAST(COUNT(DISTINCT RESULTS.DRIVERID) AS REAL) * 100.0 / COUNT(*) AS COMPLETION_RATE FROM RACES JOIN RESULTS ON RACES.RACEID = RESULTS.RACEID WHERE RACES.DATE = '1983-07-16';
