-- ----------sql1------------
-- 2147483648, 2147483648, 2147483648, 49905
SELECT D.FORENAME, D.SURNAME, D.NATIONALITY, MAX(DS.POINTS) AS MAX_POINTS FROM DRIVERSTANDINGS DS INNER JOIN DRIVERS D ON DS.DRIVERID = D.DRIVERID GROUP BY DS.DRIVERID ORDER BY COUNT(DS.WINS) DESC LIMIT 1;
-- ----------sql2------------
-- NULL, NULL, NULL, NULL
SELECT T1.FORENAME, T1.SURNAME, T1.NATIONALITY, MAX(T2.POINTS) FROM DRIVERS AS T1 INNER JOIN DRIVERSTANDINGS AS T2 ON T2.DRIVERID = T1.DRIVERID WHERE T2.WINS >= 1 GROUP BY T1.FORENAME, T1.SURNAME, T1.NATIONALITY ORDER BY COUNT(T2.WINS) DESC LIMIT 1;

