-- 5
SELECT COUNT(*) AS COUNT FROM CONSTRUCTORS JOIN RESULTS ON CONSTRUCTORS.CONSTRUCTORID = RESULTS.CONSTRUCTORID WHERE CONSTRUCTORS.NATIONALITY = 'FRENCH' AND RESULTS.LAPS > 50;
