-- ----------sql1------------
-- 1
SELECT CAST(SUM(T1.COST) AS REAL) * 100.0 / SUM(T2.SPENT) AS PERCENTAGE FROM EXPENSE T1 INNER JOIN BUDGET T2 ON T1.LINK_TO_BUDGET = T2.BUDGET_ID INNER JOIN EVENT E ON T2.LINK_TO_EVENT = E.EVENT_ID WHERE E.TYPE = 'MEETING';
-- ----------sql2------------
-- 2
SELECT SUM(CASE WHEN T1.TYPE = 'MEETING' THEN T3.COST ELSE 0 END) * 100 / SUM(T3.COST) FROM EVENT AS T1 INNER JOIN BUDGET AS T2 ON T1.EVENT_ID = T2.LINK_TO_EVENT INNER JOIN EXPENSE AS T3 ON T2.BUDGET_ID = T3.LINK_TO_BUDGET;

