-- WATER, CHIPS, COOKIES
SELECT E.EXPENSE_DESCRIPTION FROM EXPENSE AS E INNER JOIN BUDGET AS B ON E.LINK_TO_BUDGET = B.BUDGET_ID WHERE E.EXPENSE_DESCRIPTION = 'WATER, CHIPS, COOKIES' ORDER BY E.COST DESC LIMIT 1;
-- ----------sql2------------
-- 730005189306191502
SELECT T2.BUDGET_ID FROM EXPENSE AS T1 INNER JOIN BUDGET AS T2 ON T1.LINK_TO_BUDGET = T2.BUDGET_ID WHERE T1.EXPENSE_DESCRIPTION = 'WATER, CHIPS, COOKIES' ORDER BY T1.COST DESC LIMIT 1;

